import { MeshTemplate } from "@divinevoxel/vlox/Mesher/Voxels/MeshTemplate";
import { DVEBRVoxelMesh } from "../Meshes/DVEBRVoxelMesh";
import { TransformNode } from "@babylonjs/core/Meshes/transformNode";
export class VoxelTemplateMesh {
    scene;
    parent;
    meshes = [];
    constructor(scene) {
        this.scene = scene;
        this.parent = new TransformNode("", scene);
    }
    disposeMeshes() {
        for (const mesh of this.meshes) {
            mesh.dispose();
        }
        this.meshes = [];
    }
    dispose() {
        this.parent.dispose();
        this.disposeMeshes();
    }
    update(template) {
        this.disposeMeshes();
        const data = MeshTemplate(template.toJSON());
        if (!data) {
            console.error(`Could not mesh voxel template`, {
                template,
                returned: data,
            });
            return;
        }
        const meshes = data[0];
        for (const subMesh of meshes) {
            const mesh = DVEBRVoxelMesh.CreateSubMesh(subMesh, this.scene, this.scene.getEngine());
            mesh.renderingGroupId = 1;
            mesh.parent = this.parent;
            this.meshes.push(mesh);
        }
    }
}
